// H8562: the ONE source of the dedup title (create/reconcile read it here).
const body = $('Webhook soft-alert').first().json.body || {};
const expected = '[soft-alert] ' + (body.scope || 'unknown') + ' ' + (body.fingerprint || '').slice(0, 8);
const matches = $input.all()
  .map(i => i.json)
  .filter(i => (i.title || '') === expected && i.state === 'open' && !i.pull_request)
  .sort((a, b) => a.number - b.number)
  .map(i => ({ number: i.number, html_url: i.html_url }));
return [{ json: { expected_title: expected, matches } }];

